// Entity with explicit index definition
@Entity
@Table(name = "orders", indexes = {
    @Index(name = "idx_customer_id", columnList = "customer_id"),
    @Index(name = "idx_order_date", columnList = "order_date")
})
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id; // Primary key is automatically indexed

    @Column(name = "customer_id")
    private Long customerId; // Indexed for fast lookups

    @Column(name = "order_date")
    private LocalDate orderDate; // Indexed for date range queries

    private BigDecimal totalAmount;
}

// Repository query that benefits from index
@Repository
public interface OrderRepository extends JpaRepository<Order, Long> {
    // Uses idx_customer_id for fast retrieval
    List<Order> findByCustomerId(Long customerId);

    // Uses idx_order_date for efficient date filtering
    List<Order> findByOrderDateBetween(LocalDate start, LocalDate end);
}

// BAD: Indexing a boolean column (low cardinality)
@Entity
@Table(name = "users", indexes = {
    @Index(name = "idx_is_active", columnList = "is_active") // Don't do this
})
public class User {
    @Id
    private Long id;

    private Boolean isActive; // Only 2 possible values — index is useless
    private String email; // High cardinality — good index candidate
}

// BAD: Indexing a write-heavy column
@Entity
@Table(name = "audit_log", indexes = {
    @Index(name = "idx_timestamp", columnList = "timestamp") // Slows inserts
})
public class AuditLog {
    @Id
    private Long id;

    private Instant timestamp; // Inserted 10,000 times/sec — avoid indexing
    private String action;
}

// GOOD: Index only frequently queried, high-cardinality columns
@Entity
@Table(name = "products", indexes = {
    @Index(name = "idx_sku", columnList = "sku") // High cardinality, frequent lookups
})
public class Product {
    @Id
    private Long id;

    @Column(unique = true)
    private String sku; // Unique per product — excellent index candidate
}

@Entity
@Table(name = "employees", indexes = {
    // Composite index: department first, then salary
    @Index(name = "idx_dept_salary", columnList = "department, salary")
})
public class Employee {
    @Id
    private Long id;

    private String department; // High cardinality, frequently queried
    private BigDecimal salary; // Lower cardinality
    private String name;
}

@Repository
public interface EmployeeRepository extends JpaRepository<Employee, Long> {
    // Uses idx_dept_salary (matches leftmost prefix)
    List<Employee> findByDepartment(String department);

    // Uses idx_dept_salary (both columns)
    List<Employee> findByDepartmentAndSalaryGreaterThan(String dept, BigDecimal salary);

    // Does NOT use idx_dept_salary (salary alone, not leftmost)
    List<Employee> findBySalaryGreaterThan(BigDecimal salary); // Full table scan

    // Uses idx_dept_salary (department is leftmost, salary in ORDER BY is bonus)
    List<Employee> findByDepartmentOrderBySalaryDesc(String department);
}

// JPA entity and repository
@Entity
@Table(name = "orders", indexes = {
    @Index(name = "idx_customer_id", columnList = "customer_id")
})
public class Order {
    @Id private Long id;
    private Long customerId;
    private LocalDate orderDate;
}

// Repository method
List<Order> findByCustomerId(Long customerId);

// JPA generates SQL (check logs):
// SELECT * FROM orders WHERE customer_id = ?

// In MySQL client, run EXPLAIN:
// EXPLAIN SELECT * FROM orders WHERE customer_id = 123;

// Good output:
// | type | key              | rows | Extra |
// | ref  | idx_customer_id  | 5    | NULL  |
// type=ref means index lookup, key shows which index, rows=5 is efficient

// Bad output:
// | type | key  | rows  | Extra       |
// | ALL  | NULL | 50000 | Using where |
// type=ALL means full table scan, no index used, scans all 50,000 rows

// In PostgreSQL, use EXPLAIN ANALYZE for actual execution:
// EXPLAIN ANALYZE SELECT * FROM orders WHERE customer_id = 123;
// Shows: Index Scan using idx_customer_id, actual time=0.023ms

@Entity
@Table(name = "orders", indexes = {
    @Index(name = "idx_created_at", columnList = "created_at"),
    @Index(name = "idx_customer_name", columnList = "customer_name")
})
public class Order {
    @Id private Long id;
    private LocalDate createdAt;
    private String customerName;
}

// BAD: Function on indexed column — bypasses index
@Query("SELECT o FROM Order o WHERE YEAR(o.createdAt) = 2024")
List<Order> findByYear(int year); // Full table scan

// GOOD: Range query uses the index
@Query("SELECT o FROM Order o WHERE o.createdAt BETWEEN :start AND :end")
List<Order> findByDateRange(LocalDate start, LocalDate end); // Uses idx_created_at

// BAD: Leading wildcard — bypasses index
@Query("SELECT o FROM Order o WHERE o.customerName LIKE %:suffix")
List<Order> findByNameSuffix(String suffix); // Full table scan

// GOOD: Trailing wildcard uses the index
@Query("SELECT o FROM Order o WHERE o.customerName LIKE :prefix%")
List<Order> findByNamePrefix(String prefix); // Uses idx_customer_name

// BAD: Implicit type conversion if customer_id is VARCHAR
List<Order> findByCustomerId(Long id); // If column is VARCHAR, index bypassed

// GOOD: Match the column type
List<Order> findByCustomerId(String id); // Uses index if types match
